#pragma once
namespace hp {
inline constexpr char webLoginPage[]=R"LOGIN(<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Home-Display · Anmeldung</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#101923;color:#edf3f9;font:16px system-ui}main{width:min(94vw,460px);padding:30px;background:#1c2a38;border:1px solid #334858;border-radius:20px}h1{margin-top:0}label{display:block;margin:18px 0}input,button{font:inherit;border:1px solid #607c90;border-radius:10px;padding:12px;min-height:48px;color:inherit;background:#263c4c;width:100%}input[type=checkbox]{width:auto;min-height:0}button{cursor:pointer;background:#217bb2;margin:8px 0}a{color:#92d2ff}.muted{color:#b8c8d5;font-size:14px}#status{min-height:24px;white-space:pre-wrap}[hidden]{display:none!important}</style><main><h1>Home-Display</h1><p>Verwaltung sicher anmelden</p><p id="status" role="status" aria-live="polite"></p><form id="login"><label>Benutzername<input id="username" value="admin" autocomplete="username" maxlength="64" required></label><label>Passwort<input id="password" type="password" autocomplete="current-password" maxlength="96" required></label><label><input id="remember" type="checkbox"> Angemeldet bleiben (30 Tage)</label><button id="submit">Anmelden</button></form><div id="signed" hidden><p>Du bist angemeldet.</p><a id="continue" href="/">Zur Übersicht</a><button id="logout">Abmelden</button></div><p class="muted">Nur auf eigenen Geräten angemeldet bleiben. Geräte-PIN und Kontenfreigaben bleiben separat geschützt. Verwende die eingerichteten Home-Display-Zugangsdaten.</p></main><script src="/login.js"></script></html>)LOGIN";
inline constexpr char webLoginScript[]=R"LOGIN('use strict';
const $=id=>document.getElementById(id);let csrf='';
const candidate=new URLSearchParams(location.search).get('next')||'/';
const next=candidate.startsWith('/')&&!candidate.startsWith('//')&&!/[\\\x00-\x1f\x7f]/.test(candidate)&&candidate.length<=1024?candidate:'/';
$('continue').href=next;
async function probe(){const r=await fetch('/api/csrf',{cache:'no-store',credentials:'same-origin'});if(r.ok){csrf=(await r.json()).token;$('login').hidden=true;$('signed').hidden=false}}
$('login').onsubmit=async event=>{event.preventDefault();$('submit').disabled=true;const args={username:$('username').value,password:$('password').value,remember:$('remember').checked};$('password').value='';try{const r=await fetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-HP-Login':'1'},body:JSON.stringify(args)});args.password='';if(!r.ok)throw Error(await r.text());location.replace(next)}catch(e){$('status').textContent=e.message}finally{args.password='';$('submit').disabled=false}};
$('logout').onclick=async()=>{try{if(!csrf)await probe();const r=await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-HP-CSRF':csrf},body:'{}'});if(!r.ok)throw Error(await r.text());csrf='';$('signed').hidden=true;$('login').hidden=false;$('status').textContent='Abgemeldet.'}catch(e){$('status').textContent=e.message}};
probe().catch(()=>{$('status').textContent='Bitte anmelden.'});
)LOGIN";
}
